import { validateWorkValue, type WorkSetValue, type WorkWindowSnapshot } from '../../shared/contracts/work-set.contract'
import type { ShelfAction,ShelfReply } from './native-shelf-actions'

/** One serialized content writer. An old completion cannot acknowledge newer input. */
export function createShelfAutosave(deps:{current:()=>WorkWindowSnapshot;hold:(value:WorkSetValue,revision:number)=>void;save:(value:WorkSetValue,revision:number,serial:number)=>Promise<WorkWindowSnapshot>;feedback:(message:string)=>void}) {
  let serial=0,version=0,base=deps.current().set.revision,value:WorkSetValue|undefined,timer:ReturnType<typeof setTimeout>|undefined,running:Promise<ShelfReply>|undefined,blocked=false,retired=false
  const waiters=new Map<number,(reply:ShelfReply)=>void>()
  const committed=(s:WorkWindowSnapshot)=>validateWorkValue({name:s.set.name,note:s.set.note,colors:s.set.colors,columns:s.set.columns,assetIds:s.set.assetIds})
  const flush=():Promise<ShelfReply>=>{
    clearTimeout(timer);timer=undefined
    if(running)return running.then(reply=>!reply.ok||blocked?reply:value?flush():reply)
    if(retired)return Promise.resolve({ok:false,message:'工作窗口已结束，未提交保存。'})
    if(blocked)return Promise.resolve({ok:false,message:'上次保存未确认，草稿保留。请核对后重试保存。'})
    if(!value)return Promise.resolve({ok:true,ack:serial})
    const submitted=structuredClone(value),stamp=version,ack=serial,revision=base
    const task=(async():Promise<ShelfReply>=>{
      try{
        const saved=await deps.save(submitted,revision,ack);base=saved.set.revision
        if(version===stamp)value=undefined;else if(value)deps.hold(value,base)
        const reply:ShelfReply={ok:true,ack};for(const [id,resolve]of waiters)if(id<=ack){waiters.delete(id);resolve(reply)}
        blocked=false;return reply
      }catch(error){blocked=true;const message=error instanceof Error?error.message:'保存未确认，草稿保留。';deps.feedback(message)
        const reply={ok:false,message};for(const resolve of waiters.values())resolve(reply);waiters.clear();return reply
      }finally{running=undefined}
    })();running=task;return task
  }
  const edit=(action:Extract<ShelfAction,{kind:'edit'}>):Promise<ShelfReply>=>{
    if(retired||action.serial<=serial)return Promise.resolve({ok:false,message:'编辑请求已失效。'})
    const s=deps.current(),next=structuredClone(value??committed(s));if(!value)base=s.set.revision
    if(action.field==='remove'){
      const ids=action.value as string[];if(ids.some(id=>!s.set.assetIds.includes(id)))throw Error('MEMBERSHIP_NOT_GRANTED')
      next.assetIds=next.assetIds.filter(id=>!ids.includes(id))
    }else if(action.field==='colors')next.colors=action.value as string[]
    else if(action.field==='name')next.name=action.value as string
    else next.note=action.value as string
    value=validateWorkValue(next);serial=action.serial;version++;try{deps.hold(value,base)}catch(error){blocked=true;const message=error instanceof Error?error.message:'恢复记录未保存，窗口保持。';deps.feedback(message);return Promise.resolve({ok:false,message})}
    const result=new Promise<ShelfReply>(resolve=>waiters.set(serial,resolve));clearTimeout(timer)
    if(!blocked)timer=setTimeout(()=>{void flush()},300)
    else{waiters.delete(serial);return Promise.resolve({ok:false,message:'上次保存未确认，当前输入保留，请核对后重试。'})}
    return result
  }
  return{edit,flush,addColor:async(color:string)=>{const next=structuredClone(value??committed(deps.current()));if(!value)base=deps.current().set.revision;next.colors=[...new Set([...next.colors,color])];value=validateWorkValue(next);version++;deps.hold(value,base);return flush()},retry:()=>{blocked=false;return flush()},rebase:(revision:number)=>{if(running)throw Error('保存正在执行，请等待结果。');base=revision;if(value)deps.hold(value,base);blocked=false;return flush()},recover:(held:WorkSetValue,revision:number)=>{value=validateWorkValue(held);version++;base=revision;deps.hold(value,base);if(base===deps.current().set.revision)timer=setTimeout(()=>{void flush()},300);else{blocked=true;deps.feedback('恢复草稿与当前工作集版本不同，输入保留，请核对后保存。')}},pending:()=>Boolean(value||running),blocked:()=>blocked,serial:()=>serial,dispose:()=>{retired=true;clearTimeout(timer);for(const resolve of waiters.values())resolve({ok:false,message:'工作窗口已结束。'});waiters.clear()}}
}
import fs from 'node:fs'
import path from 'node:path'
import {randomUUID} from 'node:crypto'
import {validateWorkValue,workId,type WorkSetValue} from '../../shared/contracts/work-set.contract'
type Held={libraryIdentity:string;id:string;revision:number;value:WorkSetValue}
/** Host-owned recovery journal; never touches Library Originals or schema. */
export function createShelfDraftStore(directory:string) {
 fs.mkdirSync(directory,{recursive:true});if(fs.lstatSync(directory).isSymbolicLink())throw Error('SHELF_DRAFT_DIRECTORY_INVALID')
 const file=path.join(directory,'drafts.v1.json'),records=new Map<string,Held>(),key=(library:string,id:string)=>JSON.stringify([library,id])
 if(fs.existsSync(file)){
  if(fs.lstatSync(file).isSymbolicLink()||fs.statSync(file).size>2*1024*1024)throw Error('SHELF_DRAFT_FILE_INVALID')
  const stored=JSON.parse(fs.readFileSync(file,'utf8'));if(stored.version!==1||!Array.isArray(stored.records)||stored.records.length>64)throw Error('SHELF_DRAFT_FILE_INVALID')
  for(const r of stored.records){const value=validateWorkValue(r.value);workId(r.libraryIdentity);workId(r.id);if(!Number.isSafeInteger(r.revision)||r.revision<1)throw Error('SHELF_DRAFT_FILE_INVALID');records.set(key(r.libraryIdentity,r.id),{...r,value})}
 }
 const persist=()=>{const text=JSON.stringify({version:1,records:[...records.values()]});if(Buffer.byteLength(text)>2*1024*1024)throw Error('SHELF_DRAFT_FULL');const temporary=path.join(directory,`${randomUUID()}.pending`);try{fs.writeFileSync(temporary,text,{flag:'wx',mode:0o600});fs.renameSync(temporary,file)}finally{if(fs.existsSync(temporary))fs.unlinkSync(temporary)}}
 return{
  read:(libraryIdentity:string,id:string)=>{const record=records.get(key(libraryIdentity,id));return record?structuredClone(record):undefined},
  put:(record:Held)=>{const id=key(workId(record.libraryIdentity),workId(record.id)),previous=records.get(id);records.set(id,{...record,value:validateWorkValue(record.value)});try{persist()}catch(e){if(previous)records.set(id,previous);else records.delete(id);throw e}},
  clear:(libraryIdentity:string,id:string,value:WorkSetValue)=>{const k=key(libraryIdentity,id),held=records.get(k);if(!held||JSON.stringify(held.value)!==JSON.stringify(value))return;records.delete(k);try{persist()}catch(e){records.set(k,held);throw e}}
 }
}
# Local Clients Share One Host And Product Workspace

Status: Accepted (2026-10-02). The user confirmed the complete design after Q1–Q8 with “我觉得没问题”.
This records the accepted architecture; current implementation and remaining acceptance are tracked separately in subsystem references and CURRENT-STATE, not inferred from this decision.

DAM's Desktop Asset Workspace and formal Browser Asset Workspace share the same React product
presentation and one Local DAM Host per explicit profile. Electron initially hosts that authority;
Desktop IPC and loopback-only Browser transport adapt to its single command, media and event boundaries.
Library locks, committed data, accounts, AI execution, native windows and shutdown remain Host-owned.

The alternative of two independent backends would split lifecycle and task state and compete for library
locks. A standalone Node Host would require replacing credential protection, native window services and
native-dependency deployment together. Retaining Electron for the first dual-client implementation keeps
those services while making the product UI independent of its transport.

Both launch entries connect to the same profile's Host. Closing a client detaches its view; explicit Exit
DAM reviews unsaved state across clients/windows and drains the Host. The shared in-product selector
supports local filesystem workflows without making paths, process execution or arbitrary IPC trusted
Browser inputs. Main workspace and work-window clients retain distinct roles, member scopes and revocable
grants. New transport/selection/identity contracts are explicit compatibility seams with synchronized callers.

Concurrent edits preserve drafts and disclose conflicts. Workspace Recovery Drafts remain device/profile
local and separate from committed asset content; recovery requires identity and save-baseline checks.
Browser business acceptance and native OS acceptance are separate evidence. Missing native tools remains
BLOCKED_UX_ACCEPTANCE, and transport tests cannot certify actual inference or restore disabled model features.

This extends ADR 0009/0486 to a formal local Browser client, without restoring retired website collection.
It preserves ADR 0485/0489's native reference-window and ownership boundaries. It does not approve real
library migration, model downloads, credential input, external inference uploads, release or publication.
Details and the confirmed interview choices are in [the dual-client design](../product/LOCAL-DUAL-CLIENT-DESIGN.md).
